insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('mejorar-la-circulacion-en-una-interseccion-congestionada','ciudades',array['tecnologia']::text[],'Mejorar la circulación en una intersección congestionada','Observa una intersección con mucho tráfico, mide cuánto se acumula y cuánto dura cada ciclo, y propón cambios simples que ordenen el paso de vehículos y peatones.','Simulación','~25 h',25,array['Tráfico','Intersecciones']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria civil ingenieria industrial matematica ingenieria de sistemas estadistica arquitectura fisica ciencia de datos conteo y medicion. modelado basico. analisis de flujos. propuesta de soluciones. hoja de calculo. un programa de dibujo. opcionalmente, python.',$a14sld${"id": "mejorar-la-circulacion-en-una-interseccion-congestionada", "area": "ciudades", "areas2": ["tecnologia"], "titulo": "Mejorar la circulación en una intersección congestionada", "resumen": "Observa una intersección con mucho tráfico, mide cuánto se acumula y cuánto dura cada ciclo, y propón cambios simples que ordenen el paso de vehículos y peatones.", "tipo": "Simulación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Tráfico", "Intersecciones"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Industrial", "Matemática", "Ingeniería de Sistemas", "Estadística", "Arquitectura", "Física", "Ciencia de Datos"], "problema": ["Una intersección congestionada hace perder tiempo a todos y aumenta los riesgos. A veces el problema no es falta de espacio sino cómo se reparten los tiempos, los giros, los paraderos o los estacionamientos informales.", "Observar con método permite proponer cambios pequeños antes de pensar en obras grandes."], "desarrollar": ["Elige una intersección y cuenta durante periodos de diez minutos cuántos vehículos y peatones pasan por cada acceso en hora punta y fuera de ella, y anota los puntos donde se forma la cola.", "Dibuja un esquema con los flujos, identifica los conflictos, propón tres cambios, como reordenar paraderos o prohibir un giro, y simula su efecto con una hoja de cálculo o un programa sencillo."], "ampliaciones": [{"titulo": "Simulación por computadora", "aporta": "programa un modelo sencillo de colas para probar tus cambios."}, {"titulo": "Peatones", "aporta": "añade cuánto espera un peatón para cruzar en cada fase."}, {"titulo": "Costo del tiempo perdido", "aporta": "calcula cuánto tiempo pierden las personas en la cola cada día."}], "objetivos": ["Medir flujos de tránsito.", "Identificar conflictos.", "Proponer cambios.", "Estimar su efecto con un modelo simple."], "habilidades": ["Conteo y medición.", "Modelado básico.", "Análisis de flujos.", "Propuesta de soluciones."], "herramientas": ["Hoja de cálculo.", "Un programa de dibujo.", "Opcionalmente, Python."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Observa desde la vereda y sin dirigir el tránsito; presenta tus ideas como propuestas y no como instrucciones."], "otroSector": "El mismo análisis sirve para colas en una ventanilla, un estacionamiento, un comedor o un centro de atención."}$a14sld$::jsonb,30),
('iluminacion-de-calles-y-visibilidad-se-ve-bien-de-noche','ciudades',array['salud','sociedad']::text[],'Iluminación de calles y visibilidad: ¿se ve bien de noche?','Evalúa qué tan bien iluminadas están las calles que usan peatones y conductores de noche, dónde hay zonas oscuras y cómo afecta eso a la visibilidad y a la sensación de seguridad.','Análisis','~20 h',20,array['Iluminación','Seguridad']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil ingenieria electrica arquitectura fisica sociologia psicologia ingenieria ambiental estadistica medicion de campo. cartografia basica. analisis de riesgos. comunicacion de resultados. una aplicacion de luxometro. un mapa en linea. hoja de calculo.',$a15sld${"id": "iluminacion-de-calles-y-visibilidad-se-ve-bien-de-noche", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "Iluminación de calles y visibilidad: ¿se ve bien de noche?", "resumen": "Evalúa qué tan bien iluminadas están las calles que usan peatones y conductores de noche, dónde hay zonas oscuras y cómo afecta eso a la visibilidad y a la sensación de seguridad.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Iluminación", "Seguridad"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Eléctrica", "Arquitectura", "Física", "Sociología", "Psicología", "Ingeniería Ambiental", "Estadística"], "problema": ["La iluminación determina si un conductor ve a un peatón a tiempo y si una persona se atreve a caminar por una calle. Postes apagados, árboles que tapan la luz o focos demasiado altos dejan zonas oscuras.", "Medir la iluminación con un método simple permite señalar dónde mejorarla primero."], "desarrollar": ["Elige un tramo de calles y recórrelo de noche, acompañado, calificando cada punto según la cantidad de luz, si los postes funcionan y si hay árboles o carteles que tapan; si puedes, usa la aplicación de luxómetro de un celular.", "Representa los resultados en un mapa de zonas claras y oscuras, relaciónalos con cruces y paraderos y propón mejoras de ubicación o mantenimiento."], "ampliaciones": [{"titulo": "Percepción de seguridad", "aporta": "pregunta a vecinos de forma anónima cuán seguros se sienten en cada tramo."}, {"titulo": "Eficiencia", "aporta": "estima qué tipo de luminaria da más luz por cada sol gastado."}, {"titulo": "Efecto de árboles", "aporta": "analiza cómo el follaje cambia la iluminación entre estaciones."}], "objetivos": ["Evaluar la iluminación con método.", "Mapear zonas oscuras.", "Relacionar luz con riesgo.", "Proponer mejoras."], "habilidades": ["Medición de campo.", "Cartografía básica.", "Análisis de riesgos.", "Comunicación de resultados."], "herramientas": ["Una aplicación de luxómetro.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Recorre de noche solo con compañía, por rutas conocidas y con permiso de tu familia si corresponde; en zonas inseguras, observa de día y usa información de vecinos.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo análisis sirve para evaluar la iluminación de un campus, de un estacionamiento o de un lugar de trabajo."}$a15sld$::jsonb,31),
('infraestructura-para-ciclistas-donde-no-hay-proteccion','ciudades',array['ambiente','salud']::text[],'Infraestructura para ciclistas: ¿dónde no hay protección?','Identifica en una zona los tramos donde quienes usan bicicleta circulan sin ciclovía o sin protección, y qué mejoras harían más seguro y atractivo moverse en bici.','Análisis','~22 h',22,array['Ciclovías','Bicicleta']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil arquitectura geografia ingenieria ambiental ingenieria industrial sociologia estadistica diseno cartografia basica. evaluacion de infraestructura. observacion de campo. priorizacion. un mapa en linea. una ficha de evaluacion. hoja de calculo.',$a16sld${"id": "infraestructura-para-ciclistas-donde-no-hay-proteccion", "area": "ciudades", "areas2": ["ambiente", "salud"], "titulo": "Infraestructura para ciclistas: ¿dónde no hay protección?", "resumen": "Identifica en una zona los tramos donde quienes usan bicicleta circulan sin ciclovía o sin protección, y qué mejoras harían más seguro y atractivo moverse en bici.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Ciclovías", "Bicicleta"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Arquitectura", "Geografía", "Ingeniería Ambiental", "Ingeniería Industrial", "Sociología", "Estadística", "Diseño"], "problema": ["Mucha gente usaría la bicicleta si se sintiera segura, pero las ciclovías suelen ser cortas, estar interrumpidas o desaparecer justo en los cruces. Algunos ciclistas van por pistas con autos a gran velocidad.", "Mapear los tramos sin protección muestra dónde se concentran los riesgos y qué conexiones faltan."], "desarrollar": ["Recorre o estudia con mapas una zona donde se use bicicleta y marca los tramos con ciclovía, los tramos compartidos con vehículos y los puntos de mayor riesgo, como cruces o salidas de estacionamientos.", "Evalúa cada tramo con criterios, como separación del tráfico, ancho y continuidad, y propón qué tramo conviene conectar o proteger primero y qué solución usarías."], "ampliaciones": [{"titulo": "Conteo de ciclistas", "aporta": "cuenta cuántas personas usan bici en distintos tramos y horarios."}, {"titulo": "Voz de ciclistas", "aporta": "entrevista a tres ciclistas sobre los puntos más peligrosos."}, {"titulo": "Red mínima", "aporta": "diseña una red mínima que conecte los lugares más importantes de la zona."}], "objetivos": ["Mapear infraestructura para bicicletas.", "Evaluar tramos con criterios.", "Identificar conexiones faltantes.", "Priorizar mejoras."], "habilidades": ["Cartografía básica.", "Evaluación de infraestructura.", "Observación de campo.", "Priorización."], "herramientas": ["Un mapa en línea.", "Una ficha de evaluación.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Si montas bicicleta para observar, usa casco y respeta las normas de tránsito."], "otroSector": "El mismo método sirve para evaluar la infraestructura para patinetes, para personas en silla de ruedas o para peatones."}$a16sld$::jsonb,32),
('mapa-de-obstaculos-que-dificultan-caminar-por-las-veredas','ciudades',array['sociedad','salud']::text[],'Mapa de obstáculos que dificultan caminar por las veredas','Mapea los obstáculos que encuentra quien camina por las veredas de una zona, como huecos, postes, comercios, autos estacionados, escalones o cables, y dónde se concentran.','Análisis','~18 h',18,array['Veredas','Obstáculos']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil geografia sociologia trabajo social estadistica ingenieria de sistemas diseno observacion de campo. clasificacion de datos. cartografia basica. propuestas de mejora. una ficha de registro. una cinta metrica. un mapa en linea.',$a17sld${"id": "mapa-de-obstaculos-que-dificultan-caminar-por-las-veredas", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "Mapa de obstáculos que dificultan caminar por las veredas", "resumen": "Mapea los obstáculos que encuentra quien camina por las veredas de una zona, como huecos, postes, comercios, autos estacionados, escalones o cables, y dónde se concentran.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Veredas", "Obstáculos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Geografía", "Sociología", "Trabajo Social", "Estadística", "Ingeniería de Sistemas", "Diseño"], "problema": ["Una vereda debería permitir caminar sin bajar a la pista. Pero hay veredas con huecos, ocupadas por puestos o autos, con postes en medio, o con desniveles que obligan a rodear.", "Estos obstáculos afectan más a niños, adultos mayores y personas con movilidad reducida, y casi nunca están registrados."], "desarrollar": ["Recorre cuatro o cinco cuadras anotando cada obstáculo con su tipo y ubicación, y mide el ancho libre de la vereda en puntos clave.", "Clasifica los obstáculos, mapea dónde se concentran, calcula qué porcentaje de las veredas es transitable para una persona en silla de ruedas y propón soluciones por tipo de obstáculo."], "ampliaciones": [{"titulo": "Por tipo de usuario", "aporta": "evalúa el recorrido como lo haría una persona con coche de bebé o con bastón."}, {"titulo": "Causas", "aporta": "investiga por qué aparece cada obstáculo y quién podría resolverlo."}, {"titulo": "Cambios en el tiempo", "aporta": "repite el recorrido semanas después y compara."}], "objetivos": ["Registrar obstáculos con un método.", "Medir anchos de veredas.", "Clasificar y mapear.", "Proponer soluciones."], "habilidades": ["Observación de campo.", "Clasificación de datos.", "Cartografía básica.", "Propuestas de mejora."], "herramientas": ["Una ficha de registro.", "Una cinta métrica.", "Un mapa en línea."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Evita señalar a personas o comercios concretos: describe el problema, no a los responsables."], "otroSector": "El mismo mapa de obstáculos sirve para pasillos de un hospital, un mercado, un campus o un estadio."}$a17sld$::jsonb,33),
('evaluacion-de-la-accesibilidad-de-un-edificio-publico','ciudades',array['sociedad','derecho']::text[],'Evaluación de la accesibilidad de un edificio público','Recorre un edificio público como lo haría una persona con movilidad reducida y evalúa entradas, rampas, pasillos, baños, ascensores y atención, para saber si realmente se puede usar.','Análisis','~22 h',22,array['Accesibilidad','Edificios']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil trabajo social derecho sociologia psicologia diseno ingenieria de sistemas evaluacion de accesibilidad. lectura de normas tecnicas. observacion sistematica. redaccion de informes. una ficha de evaluacion. una cinta metrica. la norma tecnica oficial.',$a18sld${"id": "evaluacion-de-la-accesibilidad-de-un-edificio-publico", "area": "ciudades", "areas2": ["sociedad", "derecho"], "titulo": "Evaluación de la accesibilidad de un edificio público", "resumen": "Recorre un edificio público como lo haría una persona con movilidad reducida y evalúa entradas, rampas, pasillos, baños, ascensores y atención, para saber si realmente se puede usar.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Accesibilidad", "Edificios"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Trabajo Social", "Derecho", "Sociología", "Psicología", "Diseño", "Ingeniería de Sistemas"], "problema": ["Un edificio puede tener rampa y aun así no ser accesible: un ascensor fuera de servicio, una puerta muy pesada, un baño sin espacio o un mostrador demasiado alto lo hacen inalcanzable para algunas personas.", "Un recorrido ordenado con una ficha de criterios permite ver qué sí funciona y qué no."], "desarrollar": ["Elige un edificio público, con permiso si es necesario, y recorre el camino de la calle hasta el servicio principal, anotando cada tramo con una ficha de criterios sobre acceso, circulación, baños, señalización y atención.", "Resume los resultados con un semáforo, indica qué barreras son las más graves y escribe recomendaciones ordenadas por urgencia y costo."], "ampliaciones": [{"titulo": "Distintas discapacidades", "aporta": "añade criterios para discapacidad visual, auditiva e intelectual."}, {"titulo": "Normas", "aporta": "compara lo observado con la norma técnica de accesibilidad vigente."}, {"titulo": "Voz de usuarios", "aporta": "pide la opinión de una persona con movilidad reducida, con su permiso."}], "objetivos": ["Aplicar una ficha de accesibilidad.", "Reconocer barreras.", "Comparar con las normas.", "Recomendar mejoras."], "habilidades": ["Evaluación de accesibilidad.", "Lectura de normas técnicas.", "Observación sistemática.", "Redacción de informes."], "herramientas": ["Una ficha de evaluación.", "Una cinta métrica.", "La norma técnica oficial."], "lineamientos": ["Pide permiso para recorrer el lugar y presenta los resultados con respeto, sin señalar culpables.", "Si trabajas con personas con discapacidad, hazlo con su consentimiento y reconociéndolas como las expertas de su experiencia."], "otroSector": "La misma evaluación sirve para un colegio, un hospital, un museo o una tienda."}$a18sld$::jsonb,34),
('rampas-entradas-escaleras-y-ascensores-de-una-institucion','ciudades',array['educacion','sociedad']::text[],'Rampas, entradas, escaleras y ascensores de una institución','Inventaría y mide las rampas, entradas, escaleras y ascensores de una institución y comprueba si cumplen medidas básicas de pendiente, ancho y seguridad.','Análisis','~18 h',18,array['Accesos','Instituciones']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil trabajo social educacion sociologia diseno ingenieria industrial derecho medicion en campo. lectura de normas. priorizacion. redaccion tecnica. cinta metrica y nivel o aplicacion de inclinometro. la norma tecnica oficial. hoja de calculo.',$a19sld${"id": "rampas-entradas-escaleras-y-ascensores-de-una-institucion", "area": "ciudades", "areas2": ["educacion", "sociedad"], "titulo": "Rampas, entradas, escaleras y ascensores de una institución", "resumen": "Inventaría y mide las rampas, entradas, escaleras y ascensores de una institución y comprueba si cumplen medidas básicas de pendiente, ancho y seguridad.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Accesos", "Instituciones"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Trabajo Social", "Educación", "Sociología", "Diseño", "Ingeniería Industrial", "Derecho"], "problema": ["La accesibilidad depende de detalles medibles: una rampa muy empinada es inútil, un ascensor pequeño no entra a una silla de ruedas y una escalera sin pasamanos es un riesgo.", "Medir estos elementos permite pasar de opiniones a datos y priorizar qué arreglar."], "desarrollar": ["Con permiso, elige una institución y registra cada rampa, entrada, escalera y ascensor, midiendo pendiente, ancho, altura de pasamanos y estado, y fotografiando solo los elementos, no a personas.", "Compara las medidas con la norma técnica, marca cuáles cumplen y cuáles no, y arma un plan priorizado de mejoras con su costo aproximado."], "ampliaciones": [{"titulo": "Mapa de accesos", "aporta": "dibuja un plano con el recorrido accesible de la institución."}, {"titulo": "Fuera de servicio", "aporta": "estudia cuánto tiempo estuvieron sin uso los ascensores y por qué."}, {"titulo": "Alternativas", "aporta": "propón soluciones de bajo costo para las barreras más graves."}], "objetivos": ["Medir elementos de accesibilidad.", "Comparar con la norma.", "Priorizar mejoras.", "Presentar un plan."], "habilidades": ["Medición en campo.", "Lectura de normas.", "Priorización.", "Redacción técnica."], "herramientas": ["Cinta métrica y nivel o aplicación de inclinómetro.", "La norma técnica oficial.", "Hoja de cálculo."], "lineamientos": ["Pide permiso a la institución y no fotografíes personas.", "Presenta los resultados como una oportunidad de mejora."], "otroSector": "El mismo inventario sirve para evaluar centros de salud, estaciones de transporte o locales comerciales."}$a19sld$::jsonb,35),
('accesibilidad-de-los-espacios-publicos-parques-plazas-y-veredas','ciudades',array['sociedad','salud']::text[],'Accesibilidad de los espacios públicos: parques, plazas y veredas','Evalúa si un parque o una plaza pueden ser usados por personas mayores, con coche de bebé, bastón o silla de ruedas, y qué cambios lo harían más inclusivo.','Análisis','~20 h',20,array['Accesibilidad','Espacios públicos']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil trabajo social geografia sociologia diseno psicologia ingenieria ambiental evaluacion de espacios. observacion sistematica. diseno inclusivo. comunicacion clara. una ficha de evaluacion. un mapa o plano en linea. una cinta metrica.',$a20sld${"id": "accesibilidad-de-los-espacios-publicos-parques-plazas-y-veredas", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "Accesibilidad de los espacios públicos: parques, plazas y veredas", "resumen": "Evalúa si un parque o una plaza pueden ser usados por personas mayores, con coche de bebé, bastón o silla de ruedas, y qué cambios lo harían más inclusivo.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Accesibilidad", "Espacios públicos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Trabajo Social", "Geografía", "Sociología", "Diseño", "Psicología", "Ingeniería Ambiental"], "problema": ["Un espacio público es de todos solo si todos pueden entrar y moverse en él. Escalones, caminos de tierra, bancas muy bajas o juegos sin acceso excluyen a mucha gente sin que se note.", "Una evaluación simple con criterios claros muestra qué barreras hay y quiénes quedan fuera."], "desarrollar": ["Elige un parque o plaza y, con una ficha de criterios, evalúa entradas, caminos, pendientes, bancas, baños, iluminación y juegos, desde la mirada de tres perfiles: un niño pequeño, una persona mayor y una persona en silla de ruedas.", "Resume qué puede hacer cada perfil y qué no, mapea las barreras y propón cambios concretos de bajo costo."], "ampliaciones": [{"titulo": "Mapa de acceso", "aporta": "dibuja un plano con los caminos accesibles y los que no."}, {"titulo": "Comparar dos espacios", "aporta": "compara un parque céntrico con uno periférico."}, {"titulo": "Participación", "aporta": "invita a un grupo de adultos mayores a recorrer el lugar y recoge sus opiniones."}], "objetivos": ["Evaluar el espacio con criterios de accesibilidad.", "Considerar distintos perfiles de usuarios.", "Mapear barreras.", "Proponer cambios concretos."], "habilidades": ["Evaluación de espacios.", "Observación sistemática.", "Diseño inclusivo.", "Comunicación clara."], "herramientas": ["Una ficha de evaluación.", "Un mapa o plano en línea.", "Una cinta métrica."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Si invitas a personas a participar, que sea voluntario y con su consentimiento."], "otroSector": "El mismo método sirve para evaluar la accesibilidad de un museo, un centro comercial o un campus."}$a20sld$::jsonb,36),
('mapa-de-barreras-arquitectonicas-en-edificios-y-entornos-cercano','ciudades',array['sociedad','tecnologia']::text[],'Mapa de barreras arquitectónicas en edificios y entornos cercanos','Crea un mapa colaborativo de las barreras que encuentran las personas con movilidad reducida en edificios y calles de tu entorno, como escalones, puertas estrechas o ascensores averiados.','Prototipo','~22 h',22,array['Barreras','Mapas']::text[],array['crear','investigar']::text[],'propios',NULL,'arquitectura ingenieria civil ingenieria de sistemas trabajo social geografia diseno sociologia ciencia de datos cartografia basica. registro de campo. diseno de fichas. visualizacion de datos. un mapa en linea editable. una ficha de registro. hoja de calculo.',$a21sld${"id": "mapa-de-barreras-arquitectonicas-en-edificios-y-entornos-cercano", "area": "ciudades", "areas2": ["sociedad", "tecnologia"], "titulo": "Mapa de barreras arquitectónicas en edificios y entornos cercanos", "resumen": "Crea un mapa colaborativo de las barreras que encuentran las personas con movilidad reducida en edificios y calles de tu entorno, como escalones, puertas estrechas o ascensores averiados.", "tipo": "Prototipo", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Barreras", "Mapas"], "intencion": ["crear", "investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Ingeniería de Sistemas", "Trabajo Social", "Geografía", "Diseño", "Sociología", "Ciencia de Datos"], "problema": ["Las barreras arquitectónicas están por todas partes pero rara vez están registradas. Quien necesita una rampa descubre que no existe cuando ya llegó.", "Un mapa que muestre dónde hay barreras, de qué tipo y qué tan graves son sirve a quienes se desplazan y a quienes quieren mejorar el entorno."], "desarrollar": ["Define un sistema de categorías de barreras y una ficha corta de registro, y recorre una zona pequeña anotando cada barrera con su ubicación general, tipo y gravedad.", "Construye un mapa interactivo o un plano con los puntos, calcula cuántas barreras hay por cuadra y presenta el resultado con recomendaciones para los tres puntos más graves."], "ampliaciones": [{"titulo": "Registro colaborativo", "aporta": "diseña cómo otras personas podrían añadir barreras al mapa."}, {"titulo": "Relación con el mapa positivo", "aporta": "combínalo con el mapa de lugares accesibles."}, {"titulo": "Seguimiento", "aporta": "registra cuáles barreras se corrigen con el tiempo."}], "objetivos": ["Definir categorías de barreras.", "Registrar con método.", "Representar en un mapa.", "Priorizar los puntos más graves."], "habilidades": ["Cartografía básica.", "Registro de campo.", "Diseño de fichas.", "Visualización de datos."], "herramientas": ["Un mapa en línea editable.", "Una ficha de registro.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "Registra la ubicación aproximada de lugares públicos y no datos de viviendas ni de personas.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo mapa colaborativo sirve para registrar huecos, luminarias malogradas, basura o puntos de acumulación de agua."}$a21sld$::jsonb,37),
('redisenar-la-distribucion-de-un-espacio-publico-para-distintas-n','ciudades',array['arte','sociedad']::text[],'Rediseñar la distribución de un espacio público para distintas necesidades','Diseña de nuevo un espacio público existente para que lo puedan usar con comodidad niños, personas mayores, personas con movilidad reducida y todos los demás.','Plan','3 a 5 semanas',28,array['Diseño inclusivo','Espacio público']::text[],array['crear']::text[],'ficticios',NULL,'arquitectura diseno ingenieria civil sociologia trabajo social psicologia ingenieria ambiental geografia diseno inclusivo. planos y bocetos. pensamiento creativo. presentacion de propuestas. un programa de dibujo o planos. carton para maqueta. un editor de presentaciones.',$a22sld${"id": "redisenar-la-distribucion-de-un-espacio-publico-para-distintas-n", "area": "ciudades", "areas2": ["arte", "sociedad"], "titulo": "Rediseñar la distribución de un espacio público para distintas necesidades", "resumen": "Diseña de nuevo un espacio público existente para que lo puedan usar con comodidad niños, personas mayores, personas con movilidad reducida y todos los demás.", "tipo": "Plan", "tiempo": "3 a 5 semanas", "horas": 28, "etiquetas": ["Diseño inclusivo", "Espacio público"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Arquitectura", "Diseño", "Ingeniería Civil", "Sociología", "Trabajo Social", "Psicología", "Ingeniería Ambiental", "Geografía"], "problema": ["Muchos espacios públicos están pensados para un usuario promedio imaginario: adulto, ágil y sin equipaje. Los demás tienen que adaptarse, y a veces no pueden.", "Diseñar pensando en la diversidad de necesidades desde el inicio suele beneficiar a todos."], "desarrollar": ["Elige una plaza, un patio o una vereda real, haz un plano simple con medidas aproximadas y define cinco perfiles de usuarios con necesidades distintas.", "Detecta qué conflictos hay entre esas necesidades, propón una nueva distribución en un plano o un modelo y explica cómo responde a cada perfil."], "ampliaciones": [{"titulo": "Maqueta", "aporta": "construye una maqueta sencilla con cartón."}, {"titulo": "Presupuesto", "aporta": "estima el costo de cada cambio del diseño."}, {"titulo": "Consulta", "aporta": "muestra el diseño a cinco usuarios y ajusta según sus comentarios."}], "objetivos": ["Definir perfiles de usuarios.", "Detectar conflictos de uso.", "Diseñar una distribución inclusiva.", "Justificar las decisiones."], "habilidades": ["Diseño inclusivo.", "Planos y bocetos.", "Pensamiento creativo.", "Presentación de propuestas."], "herramientas": ["Un programa de dibujo o planos.", "Cartón para maqueta.", "Un editor de presentaciones."], "lineamientos": ["Presenta la propuesta como una idea de diseño y no como un proyecto aprobado.", "Si invitas a personas a opinar, que sea voluntario y respetuoso."], "otroSector": "El mismo ejercicio sirve para rediseñar una cocina, un aula, una oficina de atención o una estación."}$a22sld$::jsonb,38),
('orientacion-dentro-de-un-edificio-se-encuentra-el-camino-sin-pre','ciudades',array['sociedad','arte']::text[],'Orientación dentro de un edificio: ¿se encuentra el camino sin preguntar?','Evalúa si las personas pueden encontrar su camino dentro de un edificio grande, como un hospital o una universidad, y propone mejoras en carteles, colores y mapas.','Análisis','~18 h',18,array['Señalización','Orientación']::text[],array['investigar','crear']::text[],'propios',NULL,'arquitectura diseno psicologia ingenieria industrial ingenieria de sistemas comunicaciones educacion ingenieria civil pruebas de usabilidad. observacion. diseno de informacion. comunicacion visual. un plano del edificio. un programa de diseno. cronometro.',$a23sld${"id": "orientacion-dentro-de-un-edificio-se-encuentra-el-camino-sin-pre", "area": "ciudades", "areas2": ["sociedad", "arte"], "titulo": "Orientación dentro de un edificio: ¿se encuentra el camino sin preguntar?", "resumen": "Evalúa si las personas pueden encontrar su camino dentro de un edificio grande, como un hospital o una universidad, y propone mejoras en carteles, colores y mapas.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Señalización", "Orientación"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Diseño", "Psicología", "Ingeniería Industrial", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Ingeniería Civil"], "problema": ["Perderse dentro de un edificio hace perder tiempo y genera estrés, y afecta más a quienes llegan por primera vez, a personas mayores o a quienes tienen urgencia.", "La orientación depende de carteles, colores, planos y de cómo está organizado el espacio."], "desarrollar": ["Elige un edificio grande y pide a cinco personas que lo visitan por primera vez que lleguen a tres destinos sin ayuda, mientras anotas cuánto tardan, dónde dudan y qué señales usan.", "Identifica los puntos de confusión, evalúa la señalización existente y diseña una propuesta con mapas, colores o rutas, y comprueba si se entiende con otras personas."], "ampliaciones": [{"titulo": "Distintos públicos", "aporta": "compara cómo se orientan jóvenes, adultos mayores y personas con discapacidad visual."}, {"titulo": "Un mapa propio", "aporta": "diseña un plano de bolsillo del edificio."}, {"titulo": "Aplicación", "aporta": "propone cómo sería una guía digital para orientarse."}], "objetivos": ["Probar la orientación con usuarios.", "Detectar puntos de confusión.", "Evaluar señalización.", "Diseñar mejoras."], "habilidades": ["Pruebas de usabilidad.", "Observación.", "Diseño de información.", "Comunicación visual."], "herramientas": ["Un plano del edificio.", "Un programa de diseño.", "Cronómetro."], "lineamientos": ["Pide permiso para realizar las pruebas y que la participación sea voluntaria.", "No registres nombres de los participantes."], "otroSector": "El mismo estudio sirve para orientación en estaciones, aeropuertos, ferias o sitios web."}$a23sld$::jsonb,39),
('que-tan-habitable-es-una-vivienda','ciudades',array['salud','sociedad']::text[],'¿Qué tan habitable es una vivienda?','Crea y aplica una ficha para medir cuán habitable es una vivienda según espacio, luz, ventilación, humedad, ruido, seguridad y acceso a servicios.','Análisis','~20 h',20,array['Vivienda','Habitabilidad']::text[],array['investigar']::text[],'propios',NULL,'arquitectura ingenieria civil trabajo social sociologia ingenieria ambiental salud publica psicologia estadistica diseno de instrumentos. evaluacion de condiciones. visualizacion de datos. propuestas de mejora. hoja de calculo. un editor de graficos. una ficha de evaluacion.',$a24sld${"id": "que-tan-habitable-es-una-vivienda", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "¿Qué tan habitable es una vivienda?", "resumen": "Crea y aplica una ficha para medir cuán habitable es una vivienda según espacio, luz, ventilación, humedad, ruido, seguridad y acceso a servicios.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Vivienda", "Habitabilidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Trabajo Social", "Sociología", "Ingeniería Ambiental", "Salud Pública", "Psicología", "Estadística"], "problema": ["Una vivienda no es solo un techo: debe ofrecer condiciones para vivir con salud y dignidad, como suficiente espacio, aire, luz, agua, privacidad y seguridad.", "Medir la habitabilidad con criterios claros permite comparar y detectar los problemas más urgentes."], "desarrollar": ["Diseña una ficha con entre diez y quince criterios de habitabilidad, y aplícala a tu propia vivienda o a un caso ficticio, puntuando cada aspecto.", "Presenta los resultados en un gráfico tipo radar, señala los puntos más débiles y propón mejoras posibles de bajo costo."], "ampliaciones": [{"titulo": "Comparar viviendas", "aporta": "aplica la ficha a dos casos ficticios y compara."}, {"titulo": "Pesos de los criterios", "aporta": "analiza qué criterios son más importantes para distintas personas."}, {"titulo": "Versión para un barrio", "aporta": "adapta la ficha para evaluar un conjunto de viviendas."}], "objetivos": ["Diseñar criterios de habitabilidad.", "Aplicar una ficha con método.", "Visualizar resultados.", "Proponer mejoras."], "habilidades": ["Diseño de instrumentos.", "Evaluación de condiciones.", "Visualización de datos.", "Propuestas de mejora."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Una ficha de evaluación."], "lineamientos": ["Aplícalo solo a tu vivienda o a casos ficticios; no evalúes la vivienda de otras personas sin su consentimiento.", "No expongas condiciones de vida de personas identificables."], "otroSector": "La misma ficha sirve para evaluar aulas, dormitorios universitarios, albergues o locales de trabajo."}$a24sld$::jsonb,40),
('iluminacion-y-ventilacion-natural-en-distintos-tipos-de-vivienda','ciudades',array['ambiente','salud']::text[],'Iluminación y ventilación natural en distintos tipos de vivienda','Mide y compara cuánta luz natural y cuánta ventilación tienen distintos tipos de vivienda y cómo cambian a lo largo del día.','Análisis','~22 h',22,array['Confort ambiental','Vivienda']::text[],array['investigar']::text[],'propios',NULL,'arquitectura ingenieria ambiental fisica ingenieria civil ingenieria mecanica diseno estadistica ingenieria electrica medicion con instrumentos simples. analisis comparativo. esquemas de diseno. interpretacion de resultados. una aplicacion de luxometro. un termometro. hoja de calculo.',$a25sld${"id": "iluminacion-y-ventilacion-natural-en-distintos-tipos-de-vivienda", "area": "ciudades", "areas2": ["ambiente", "salud"], "titulo": "Iluminación y ventilación natural en distintos tipos de vivienda", "resumen": "Mide y compara cuánta luz natural y cuánta ventilación tienen distintos tipos de vivienda y cómo cambian a lo largo del día.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Confort ambiental", "Vivienda"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Ambiental", "Física", "Ingeniería Civil", "Ingeniería Mecánica", "Diseño", "Estadística", "Ingeniería Eléctrica"], "problema": ["Una vivienda bien orientada y con ventanas adecuadas necesita menos luz artificial y menos aire acondicionado, y es más saludable. Pero muchas viviendas tienen cuartos oscuros o sin ventilación cruzada.", "Medirlo con instrumentos simples ayuda a entender cómo influye el diseño en el confort."], "desarrollar": ["Elige dos o tres espacios con diseños distintos, por ejemplo un departamento, una casa con patio y un cuarto interior, y mide en tres horarios la luz con una aplicación de luxómetro y la temperatura con un termómetro.", "Dibuja el esquema de cada espacio con la posición de las ventanas, compara los resultados y propón cambios sencillos para mejorar luz y ventilación."], "ampliaciones": [{"titulo": "Orientación solar", "aporta": "analiza cómo influye hacia dónde miran las ventanas."}, {"titulo": "Uso de color", "aporta": "prueba cómo cambian los resultados con paredes claras u oscuras."}, {"titulo": "Ahorro de energía", "aporta": "estima cuánta electricidad se ahorraría con mejor luz natural."}], "objetivos": ["Medir luz y temperatura.", "Relacionar diseño con confort.", "Comparar tipos de vivienda.", "Proponer mejoras."], "habilidades": ["Medición con instrumentos simples.", "Análisis comparativo.", "Esquemas de diseño.", "Interpretación de resultados."], "herramientas": ["Una aplicación de luxómetro.", "Un termómetro.", "Hoja de cálculo."], "lineamientos": ["Mide solo espacios propios o con permiso y no incluyas direcciones ni datos de los ocupantes.", "No hagas cambios estructurales sin consultar a un profesional."], "otroSector": "El mismo análisis sirve para aulas, talleres, invernaderos o locales comerciales."}$a25sld$::jsonb,41),
('analisis-comparativo-de-distintos-tipos-de-vivienda','ciudades',array['sociedad','negocios']::text[],'Análisis comparativo de distintos tipos de vivienda','Compara viviendas de distinto tipo, como casa, departamento, cuarto alquilado o vivienda autoconstruida, según costo, espacio, servicios, seguridad y comodidad.','Análisis','~22 h',22,array['Vivienda','Comparación']::text[],array['investigar']::text[],'publicos',NULL,'arquitectura ingenieria civil economia sociologia trabajo social geografia estadistica administracion busqueda de informacion. analisis comparativo. lectura de datos de vivienda. comunicacion clara. hoja de calculo. datos publicos de censos y encuestas de hogares. un editor de graficos.',$a26sld${"id": "analisis-comparativo-de-distintos-tipos-de-vivienda", "area": "ciudades", "areas2": ["sociedad", "negocios"], "titulo": "Análisis comparativo de distintos tipos de vivienda", "resumen": "Compara viviendas de distinto tipo, como casa, departamento, cuarto alquilado o vivienda autoconstruida, según costo, espacio, servicios, seguridad y comodidad.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Vivienda", "Comparación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Economía", "Sociología", "Trabajo Social", "Geografía", "Estadística", "Administración"], "problema": ["No todas las viviendas ofrecen lo mismo ni cuestan lo mismo. Comparar tipos de vivienda ayuda a entender por qué las personas eligen una u otra y qué sacrifican.", "También muestra qué problemas son propios de cada tipo, como hacinamiento, humedad o falta de áreas comunes."], "desarrollar": ["Con información pública, como avisos, censos o estudios, describe cuatro tipos de vivienda con rangos de costo, tamaño típico, acceso a servicios y condiciones.", "Compara los tipos en una tabla, relaciónalos con distintos tipos de hogares y escribe qué vivienda convendría a una familia, a un estudiante y a una persona mayor, con los límites de tu análisis."], "ampliaciones": [{"titulo": "Costo por metro cuadrado", "aporta": "calcula y compara cuánto cuesta cada espacio."}, {"titulo": "Proceso de construcción", "aporta": "describe cómo se construye cada tipo y cuánto tarda."}, {"titulo": "Evolución", "aporta": "analiza cómo ha cambiado el tipo de vivienda más común en tu ciudad."}], "objetivos": ["Reunir datos públicos de vivienda.", "Comparar tipos con criterios.", "Relacionarlos con necesidades.", "Explicar los límites del análisis."], "habilidades": ["Búsqueda de información.", "Análisis comparativo.", "Lectura de datos de vivienda.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Datos públicos de censos y encuestas de hogares.", "Un editor de gráficos."], "lineamientos": ["Cita las fuentes y fecha los datos; los precios varían mucho entre zonas.", "Evita juicios de valor sobre las personas que habitan cada tipo de vivienda."], "otroSector": "La misma comparación sirve para evaluar tipos de oficinas, de escuelas o de espacios de comercio."}$a26sld$::jsonb,42)
